import {
  addDoc,
  collection,
  deleteDoc,
  doc,
  getDocs,
  orderBy,
  query,
  serverTimestamp,
  updateDoc,
  where,
} from "firebase/firestore";
import type { Activity } from "../../features/admin/types";

export type CreateActivityInput = {
  itineraryId: string;
  itineraryDayId: string;
  dayNumber: number;
  city: string;
  name: string;
  description: string;
  startTime?: string;
  durationMinutes?: number;
  priority?: number;
  category?: string;
  location?: string;
  observations?: string;
  cost?: number;
  costBreakdown?: string[];
  price?: number;
  createdBy: string;
};

export type UpdateActivityInput = Partial<
  Omit<CreateActivityInput, "createdBy" | "itineraryId" | "itineraryDayId" | "dayNumber">
> & { updatedBy: string };

async function getDb() {
  const { db } = await import("../../lib/firebase");
  return db;
}

export async function createActivity(input: CreateActivityInput): Promise<string> {
  const db = await getDb();
  const ref = await addDoc(collection(db, "activities"), {
    itineraryId: input.itineraryId,
    itineraryDayId: input.itineraryDayId,
    dayNumber: input.dayNumber,
    city: input.city,
    name: input.name,
    description: input.description,
    startTime: input.startTime ?? null,
    durationMinutes: input.durationMinutes ?? null,
    priority: input.priority ?? null,
    category: input.category ?? null,
    location: input.location ?? null,
    observations: input.observations ?? null,
    cost: input.cost ?? null,
    costBreakdown: input.costBreakdown ?? [],
    price: input.price ?? null,
    createdAt: serverTimestamp(),
    updatedAt: serverTimestamp(),
    createdBy: input.createdBy,
    updatedBy: null,
  });
  return ref.id;
}

export async function updateActivity(id: string, input: UpdateActivityInput): Promise<void> {
  const db = await getDb();
  const payload: Record<string, unknown> = { updatedAt: serverTimestamp() };
  for (const [key, value] of Object.entries(input)) {
    payload[key] = value ?? null;
  }
  await updateDoc(doc(db, "activities", id), payload);
}

export async function listActivitiesByDay(itineraryDayId: string): Promise<(Activity & { id: string })[]> {
  const db = await getDb();
  const q = query(
    collection(db, "activities"),
    where("itineraryDayId", "==", itineraryDayId),
    orderBy("startTime", "asc")
  );
  const snap = await getDocs(q);
  return snap.docs.map((d) => ({ id: d.id, ...(d.data() as Activity) }));
}

export async function listActivitiesByItinerary(itineraryId: string): Promise<(Activity & { id: string })[]> {
  const db = await getDb();
  const q = query(
    collection(db, "activities"),
    where("itineraryId", "==", itineraryId),
    orderBy("dayNumber", "asc")
  );
  const snap = await getDocs(q);
  return snap.docs.map((d) => ({ id: d.id, ...(d.data() as Activity) }));
}

export async function deleteActivity(id: string): Promise<void> {
  const db = await getDb();
  await deleteDoc(doc(db, "activities", id));
}
