import {
  collection,
  deleteDoc,
  doc,
  getDocs,
  query,
  serverTimestamp,
  setDoc,
  updateDoc,
  where,
  limit,
} from "firebase/firestore";
import { updateDoc as firestoreUpdateDoc } from "firebase/firestore";
import type { SharedAccess } from "../../features/admin/types";

async function getDb() {
  const { db } = await import("../../lib/firebase");
  return db;
}

// ID compuesto {itineraryId}_{uid} — decisión confirmada en MODULE.md
function sharedAccessId(itineraryId: string, userId: string): string {
  return `${itineraryId}_${userId}`;
}

export async function shareItineraryWithUser(
  itineraryId: string,
  userId: string,
  createdBy: string,
  expiresAt?: Date
): Promise<void> {
  const db = await getDb();
  const id = sharedAccessId(itineraryId, userId);
  await setDoc(doc(db, "sharedAccess", id), {
    itineraryId,
    userId,
    permission: "read",
    status: "active",
    sharedAt: serverTimestamp(),
    expiresAt: expiresAt ?? null,
    createdBy,
  });
}

export async function revokeSharedAccess(itineraryId: string, userId: string): Promise<void> {
  const db = await getDb();
  const id = sharedAccessId(itineraryId, userId);
  await updateDoc(doc(db, "sharedAccess", id), {
    status: "revoked",
  });
}

export async function listSharedAccessByItinerary(
  itineraryId: string
): Promise<(SharedAccess & { id: string })[]> {
  const db = await getDb();
  const q = query(
    collection(db, "sharedAccess"),
    where("itineraryId", "==", itineraryId)
  );
  const snap = await getDocs(q);
  return snap.docs.map((d) => ({ id: d.id, ...(d.data() as SharedAccess) }));
}

// Genera un shareToken UUID v4 y actualiza el itinerario.
// En producción, mover a Cloud Function para que la generación sea server-side.
export async function generateShareToken(
  itineraryId: string,
  updatedBy: string
): Promise<string> {
  const db = await getDb();
  const token = crypto.randomUUID();
  await firestoreUpdateDoc(doc(db, "itineraries", itineraryId), {
    shareToken: token,
    sharedAt: serverTimestamp(),
    status: "shared",
    updatedAt: serverTimestamp(),
    updatedBy,
  });
  return token;
}

export async function revokeShareToken(itineraryId: string, updatedBy: string): Promise<void> {
  const db = await getDb();
  await firestoreUpdateDoc(doc(db, "itineraries", itineraryId), {
    shareToken: null,
    sharedAt: null,
    status: "approved",
    updatedAt: serverTimestamp(),
    updatedBy,
  });
}

// Busca un itinerario por su shareToken (para la vista pública del cliente).
export async function getItineraryByToken(
  token: string
): Promise<{ id: string; [key: string]: unknown } | null> {
  const db = await getDb();
  const q = query(
    collection(db, "itineraries"),
    where("shareToken", "==", token),
    where("status", "==", "shared"),
    limit(1)
  );
  const snap = await getDocs(q);
  if (snap.empty) return null;
  const d = snap.docs[0];
  return { id: d.id, ...d.data() };
}
